DROP VIEW "invoice_with_sum";--> statement-breakpoint
DROP VIEW "items_with_tax";--> statement-breakpoint
ALTER TABLE "invoice_item" ALTER COLUMN "label" SET DATA TYPE text USING "label"::text;--> statement-breakpoint
ALTER TABLE "invoice_item" ALTER COLUMN "note" SET DATA TYPE text USING "note"::text;

CREATE VIEW "items_with_tax" WITH (security_invoker = true) AS (select "invoice_item"."id", "invoice_item"."invoice_id", "invoice_item"."label", "invoice_item"."note", "invoice_item"."quantity", "invoice_item"."unit", "invoice_item"."unit_cost", "invoice_item"."net_amount", "invoice_item"."order", "invoice_item"."user_id", "invoice_item"."config_id", "config"."tax_registration", ((1 + COALESCE(sum("tax"."rate") * "config"."tax_registration"::INT, 0)) * "invoice_item"."net_amount")::NUMERIC(15, 4) as "gross_amount" from "invoice_item" left join "item_tax" on "item_tax"."item_id" = "invoice_item"."id" left join "tax" on "item_tax"."tax_id" = "tax"."id" left join "invoice" on "invoice_item"."invoice_id" = "invoice"."id" left join "config" on "invoice"."config_id" = "config"."id" group by "invoice_item"."id", "config"."id");
CREATE VIEW "invoice_with_sum" WITH (security_invoker = true) AS (select "invoice"."id", "invoice"."user_id", "invoice"."client_data_id", "invoice"."title", "invoice"."description", "invoice"."created_at", "invoice"."issued_at", "invoice"."issue_year", "invoice"."due_at", "invoice"."index", "invoice"."year_index", "invoice"."config_id", "config"."tax_registration", "config"."currency", sum("items_with_tax"."net_amount") as "net_total", sum("items_with_tax"."gross_amount") as "gross_total" from "invoice" inner join "config" on "invoice"."config_id" = "config"."id" left join "items_with_tax" on "items_with_tax"."invoice_id" = "invoice"."id" group by "invoice"."id", "config"."id");--> statement-breakpoint
